create table if not exists worker_entries(id uuid primary key default gen_random_uuid(),report_id uuid not null references daily_reports(id) on delete cascade,worker_id uuid not null references workers(id),attendance_factor numeric(3,2) not null check(attendance_factor in (0,0.5,1)),overtime_hours numeric(8,2) not null default 0,overtime_amount numeric(14,2) not null default 0,advance numeric(14,2) not null default 0,payable numeric(14,2) not null default 0,created_at timestamptz not null default now(),unique(report_id,worker_id));
create table if not exists contractor_entries(id uuid primary key default gen_random_uuid(),report_id uuid not null references daily_reports(id) on delete cascade,contractor_id uuid not null references contractors(id),quantity numeric(14,3) not null,unit_rate numeric(14,2) not null,amount numeric(14,2) not null,created_at timestamptz not null default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',split_part(new.email,'@',1))) on conflict (id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
alter table worker_entries enable row level security; alter table contractor_entries enable row level security;
create policy "project worker entries" on worker_entries for all using(exists(select 1 from daily_reports r where r.id=report_id and is_project_member(r.project_id))) with check(exists(select 1 from daily_reports r where r.id=report_id and is_project_member(r.project_id)));
create policy "project contractor entries" on contractor_entries for all using(exists(select 1 from daily_reports r where r.id=report_id and is_project_member(r.project_id))) with check(exists(select 1 from daily_reports r where r.id=report_id and is_project_member(r.project_id)));